def affordable_cables(adj, budget):
    weights = []
    for u in adj:
        for v, w in adj[u]:
            if v > u:
                weights.append(w)
    weights.sort()
    spent = 0
    count = 0
    for w in weights:
        if spent + w <= budget:
            spent += w
            count += 1
        else:
            break
    return count


