def has_cycle(adj):
    visited = set()
    for start in adj:
        if start in visited:
            continue
        stack = [(start, -1)]
        while stack:
            node, parent = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for v in adj[node]:
                if v not in visited:
                    stack.append((v, node))
                elif v != parent:
                    return True
    return False


