def min_hops(adj, src, dst):
    if src == dst:
        return 0
    dist = {src: 0}
    queue = [src]
    while queue:
        node = queue.pop(0)
        for v in adj[node]:
            if v not in dist:
                dist[v] = dist[node] + 1
                if v == dst:
                    return dist[v]
                queue.append(v)
    return -1


