def hop_distances(adj, src):
    dist = {}
    for v in adj:
        dist[v] = -1
    dist[src] = 0
    queue = [src]
    while queue:
        node = queue.pop(0)
        for v in adj[node]:
            if dist[v] == -1:
                dist[v] = dist[node] + 1
                queue.append(v)
    return [dist[v] for v in range(len(dist))]


