def mst_weight(V, edges):
    parent = []
    for v in range(V):
        parent.append(v)

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    total = 0
    for w, u, v in sorted(edges):
        ru = find(u)
        rv = find(v)
        if ru != rv:
            parent[ru] = rv
            total += w
    return total


def main():
