def topo_order(adj):
    V = len(adj)
    indeg = {}
    for u in adj:
        indeg[u] = 0
    for u in adj:
        for v in adj[u]:
            indeg[v] += 1
    order = []
    placed = set()
    while len(order) < V:
        best = -1
        for v in range(V):
            if v not in placed and indeg[v] == 0:
                best = v
                break
        order.append(best)
        placed.add(best)
        for w in adj[best]:
            indeg[w] -= 1
    return order


