def is_bipartite(adj):
    color = {}
    for start in adj:
        if start not in color:
            color[start] = 0
            stack = [start]
            while stack:
                node = stack.pop()
                for v in adj[node]:
                    if v not in color:
                        color[v] = 1 - color[node]
                        stack.append(v)
                    elif color[v] == color[node]:
                        return False
    return True


