def count_islands(grid, R, C):
    seen = []
    for r in range(R):
        seen.append([False] * C)
    count = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == "1" and not seen[r][c]:
                count += 1
                stack = [(r, c)]
                seen[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr = cr + dr
                        nc = cc + dc
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == "1" and not seen[nr][nc]:
                            seen[nr][nc] = True
                            stack.append((nr, nc))
    return count


def main():
    R, C = map(int, input().split())
    grid = []
    for _ in range(R):
        grid.append(input().strip())
    print(count_islands(grid, R, C))


